%   data: {"dataType":"text","outputData":{"text":"    StudentID         Case         LoadMultiplier    Objective    StudyNodes\n    _________    ______________    ______________    _________    __________\n\n    2.424e+08    \"case_nongcun\"        1.042            \"A\"       \"[4 9 14]\"\n\n","truncated":false}}
